import React from "react";
import { Link } from "react-router-dom";
import '../App.css';

function Dashboard() {
  const user = JSON.parse(localStorage.getItem("user"));

  if (!user) {
    return <p>Please log in first.</p>;
  }

  return (
    <div className="dashboard-container">
      <h2>Welcome, {user.name}</h2>
      <p>Your role: {user.role}</p>

      {user.role === "seller" && (
        <div className="dashboard-links" style={{ marginTop: "20px" }}>
          <ul style={{ listStyle: "none", padding: 0 }}>
            <li style={{ marginBottom: "10px" }}>
              <Link to="/add-listing" style={{ color: "#4A90E2", fontWeight: "bold" }}>Add New Listing</Link>
            </li>
            <li style={{ marginBottom: "10px" }}>
              <Link to="/view-listings" style={{ color: "#4A90E2", fontWeight: "bold" }}>View/Edit Listings</Link>
            </li>
          </ul>
        </div>
      )}
    </div>
  );
}

export default Dashboard;
